insert into public.lessons (id, unit_id, title, lesson_type, scenario, assessment, sort_order) values
  ('PRE-A0.U01.L01', 'PRE-A0.U01', 'Recognize the alphabet', 'phonics', 'A a, B b, C c, D d. Say the names; point to the matching forms. Avoid introducing all letter sounds at once.', '["record each correct response; target is 20/26 identification and 18/26 matching. The answer is the identical letter in the other case, not a letter that merely looks similar."]'::jsonb, 1),
  ('PRE-A0.U01.L02', 'PRE-A0.U01', 'Match uppercase and lowercase', 'phonics', 'match 24/26 case pairs without relying on alphabet order.', '["24/26 pairs correct in two shuffled rounds. If not, practice only the missed pairs and retest with cards in a different order."]'::jsonb, 2),
  ('PRE-A0.U01.L03', 'PRE-A0.U01', 'Say letter names; do not confuse names with sounds', 'phonics', 'name 20/26 shown letters and select the spoken letter name when it is said aloud.', '["8/10 mixed name-versus-sound prompts correct. Repeat using different taught letters if missed."]'::jsonb, 3),
  ('PRE-A0.U01.L04', 'PRE-A0.U01', 'Write recognizable letter forms', 'phonics', 'form at least 20 lowercase and 20 uppercase letters so a reader can identify them.', '["teacher identifies at least 20/26 uppercase and lowercase attempts without being told which letter was intended."]'::jsonb, 4),
  ('PRE-A0.U02.L01', 'PRE-A0.U02', 'Vowels, consonants, and speech sounds', 'phonics', 'identify the five vowel letters and classify the other 21 letters as consonant letters; identify the first sound in 4/5 taught words.', '["5/5 vowel-letter identification and 4/5 initial sounds. If letter categories are secure but sound responses are weak, keep the categories and reteach listening separately."]'::jsonb, 5),
  ('PRE-A0.U02.L02', 'PRE-A0.U02', 'Hear and find first, middle, and last sounds', 'phonics', 'identify the first and last sounds in 4/5 familiar words and the short vowel sound in 3/4 spoken CVC words.', '["at least 4/5 initial/final responses and 3/4 vowel-pattern matches. If spelling is not yet known, assess oral identification with picture cards."]'::jsonb, 6),
  ('PRE-A0.U02.L03', 'PRE-A0.U02', 'Contrast sounds without guessing from letter names', 'phonics', 'distinguish at least 4/5 teacher-spoken contrasts from the taught set, using picture or word cards.', '["4/5 selections across the pairs. If not met, use one contrast at a time, slow the model slightly, and retest with order changed. Do not tell the learner that their accent is wrong."]'::jsonb, 7),
  ('PRE-A0.U02.L04', 'PRE-A0.U02', 'Short-vowel CVC patterns', 'phonics', 'blend and read 8/10 taught CVC words with short a, e, i, o, u.', '["8/10 correctly blended, including one example from each taught vowel set over the lesson sequence. If missed, sort by vowel and blend three words from the weak group before reassessment."]'::jsonb, 8),
  ('PRE-A0.U03.L01', 'PRE-A0.U03', 'Blend, segment, and change one sound', 'phonics', 'read 8/10 taught CVC words and spell 4/5 from oral dictation using sound-to-letter mapping.', '["8/10 reading and 4/5 spelling. Remediate only the missed position (initial, middle, final) with new examples such as pin/pan or map/mat."]'::jsonb, 9),
  ('PRE-A0.U03.L02', 'PRE-A0.U03', 'Word families, rhyme, and syllables', 'phonics', 'identify a rhyming word for 4/5 spoken prompts and clap the syllables in 4/5 familiar words.', '["4/5 rhymes and 4/5 syllable counts. For a missed item, speak it naturally, tap beats, and repeat without written prompts."]'::jsonb, 10),
  ('PRE-A0.U03.L03', 'PRE-A0.U03', 'Common consonant teams: `sh`, `ch`, `th`, `ck`', 'phonics', 'recognize sh, ch, and ck in taught words and decode 6/8 taught words.', '["identify 4 teams correctly and read 6/8 taught words with understandable sound sequence. Remediation: contrast one team against a known CVC word (sip/ship, chip/tip) with pictures."]'::jsonb, 11),
  ('PRE-A0.U03.L04', 'PRE-A0.U03', 'Silent `e` as a useful pattern', 'phonics', 'distinguish four taught short-vowel/e word pairs by listening and match each written word to its spoken form.', '["7/8 correct. If not, return to one pair at a time and use clear picture meanings; do not teach a universal “vowel says its name” rule."]'::jsonb, 12),
  ('PRE-A0.U04.L01', 'PRE-A0.U04', 'Copy letters, labels, and word spaces', 'phonics', 'copy 8/10 familiar labels legibly and identify the word boundary in 4/5 short phrases.', '["8/10 labels recognized by a second reader; 4/5 boundaries marked. If handwriting obscures spelling, allow letter cards or oral spelling to separate knowledge from motor control."]'::jsonb, 13),
  ('PRE-A0.U04.L02', 'PRE-A0.U04', 'Spell and retrieve familiar words', 'phonics', 'spell 8/10 familiar words from picture, oral cue, or real object.', '["8/10. For errors, sort into first sound, vowel pattern, final sound, or remembered spelling; practice that type and retest with a parallel word."]'::jsonb, 14),
  ('PRE-A0.U04.L03', 'PRE-A0.U04', 'Read familiar signs and instructions', 'phonics', 'read and follow 4/5 familiar printed one-step instructions, follow 4/5 spoken instructions, and match 4/5 classroom labels to objects.', '["4/5 printed instructions, 4/5 spoken instructions, 4/5 labels, and 2/2 text questions. Score reading, listening, and comprehension separately. If spoken comprehension fails, repeat with familiar words at a natural but slower pace; if printed reading fails, rehearse the phrase-to-action link, then test new printed commands."]'::jsonb, 15),
  ('PRE-A0.U05.L01', 'PRE-A0.U05', 'Greetings and names', 'phonics', 'complete a two-turn greeting and state a name in an understandable phrase.', '["learner initiates a greeting, says a name, and responds once without copying a written script. If anxious, rehearse with the teacher, then repeat with a partner."]'::jsonb, 16),
  ('PRE-A0.U05.L02', 'PRE-A0.U05', 'Sounds, words, and classroom response', 'phonics', 'match cat, map, sun, pen to pictures; mark the first and last letter; read left to right. Then follow the spoken commands below.', '["Which animal was mentioned? Which letter should be written? What was the final instruction?", "correctly identify 8 of 10 mixed-case letters, read 3 of 4 CVC words, and respond to 4 of 5 commands. If not, reteach letter-name/sound distinction and blend two-word sets before retrying with different items."]'::jsonb, 17),
  ('PRE-A0.U05.L03', 'PRE-A0.U05', 'Review and learner self-check', 'phonics', 'retrieve one letter, one sound, one word, one instruction, and one greeting without a model.', '[]'::jsonb, 18),
  ('PRE-A0.U05.L04', 'PRE-A0.U05', 'Integrated sound, word, and classroom check', 'phonics', 'use taught letters, decode taught words, understand instructions, and exchange names.', '[]'::jsonb, 19),
  ('A0.U01.L01', 'A0.U01', 'Subject pronouns and `be`', 'sentence_builder', 'complete 8/10 sentence prompts with the correct subject pronoun and present be.', '["8/10 correct in a new mixed set; include at least two different be forms."]'::jsonb, 1),
  ('A0.U01.L02', 'A0.U01', 'Affirmative, negative, and `be` questions', 'sentence_builder', 'turn 4/5 statements into accurate negatives and 4/5 into appropriate be questions.', '["8/10 transformations with correct order and be."]'::jsonb, 2),
  ('A0.U01.L03', 'A0.U01', 'Numbers, age, and spelling personal details', 'sentence_builder', 'identify, say, and write 18/20 numbers from 1–20 and the taught tens; state age using a complete phrase.', '["18/20 number recognition/writing including at least three teen/tens contrasts."]'::jsonb, 3),
  ('A0.U01.L04', 'A0.U01', 'A simple personal introduction', 'sentence_builder', '“My name is Lina. I am nineteen and I live in Rabat. I have one brother. My brother is a student.”', '["at least 4/5 profile details conveyed correctly; 4 sentences use be/have accurately; question uses appropriate word order. Correct errors by sorting examples into be questions and do questions."]'::jsonb, 4),
  ('A0.U01.L05', 'A0.U01', 'Days, months, dates, and birthdays', 'sentence_builder', 'sequence days and months, understand 4/5 read dates, and say or write a personal date using an appropriate preposition.', '["correctly sequence 6/7 days and 10/12 months (two rounds); 4/5 date/preposition items."]'::jsonb, 5),
  ('A0.U02.L01', 'A0.U02', 'Family and basic plural nouns', 'sentence_builder', 'identify 10 family words and form the plural of 8/10 taught regular nouns.', '["8/10 plural forms and 8/10 picture-word matches."]'::jsonb, 6),
  ('A0.U02.L02', 'A0.U02', '`a/an`, `the`, and familiar objects', 'sentence_builder', 'I have an apple. The apple is red.', '["8/10 choices, judged by beginning sound and reference."]'::jsonb, 7),
  ('A0.U02.L03', 'A0.U02', 'Basic adjectives and describing objects', 'sentence_builder', 'produce five noun phrases with a correct simple adjective-before-noun order and matching be sentence.', '["five phrases have adjective+noun order and no plural adjective ending."]'::jsonb, 8),
  ('A0.U02.L04', 'A0.U02', 'Possessive adjectives, `have/has`, and `’s`', 'sentence_builder', 'use four possessive adjectives and have/has in 8/10 descriptions; identify ownership with a name + ''s.', '["8/10 correct possessive/verb pairings and explain whose object is meant."]'::jsonb, 9),
  ('A0.U02.L05', 'A0.U02', 'Read and describe a family/home profile', 'sentence_builder', 'This is Hana''s family. Her parents are at home. Hana has one brother and two sisters. Their home is small. It has a blue door and a big kitchen.', '["4/5 factual details; writing contains at least four understandable sentences, at least one possessive and one be/have form. If not, revisit the specific earlier lesson."]'::jsonb, 10),
  ('A0.U03.L01', 'A0.U03', 'Clock time and time prepositions', 'sentence_builder', 'identify 8/10 full-hour/half-hour clock times and choose at/on/in in 8/10 taught time phrases.', '["8/10 clock matches and 4/5 prepositions."]'::jsonb, 11),
  ('A0.U03.L02', 'A0.U03', 'Everyday verbs and present-simple statements', 'role_play', 'produce 6/7 short present-simple routine sentences with a subject and correct base/third-person verb form.', '["6/7 verbs appropriate for subject."]'::jsonb, 12),
  ('A0.U03.L03', 'A0.U03', 'Frequency words and negative routines', 'sentence_builder', 'place always, usually, sometimes, and never appropriately in 4/5 sentences and form 4/5 present-simple negatives.', '["4/5 adverb placements and 4/5 negatives."]'::jsonb, 13),
  ('A0.U03.L04', 'A0.U03', '`Do/does` questions and short answers', 'sentence_builder', 'ask 4/5 present-simple questions with correct order and give a matching short answer.', '["4/5 question forms plus 4 matched short answers."]'::jsonb, 14),
  ('A0.U03.L05', 'A0.U03', 'Read a simple timetable and report a routine', 'essay_analysis', 'retrieve 4/5 timetable facts and give a short oral routine with three time phrases.', '["4/5 facts and 4/5 sentences with correct subject/verb/time phrase."]'::jsonb, 15),
  ('A0.U04.L01', 'A0.U04', 'Prepositions of place', 'sentence_builder', 'describe 5/6 object locations using a taught preposition.', '["5/6 accurate descriptions and partner can reproduce 4/5 arrangements."]'::jsonb, 16),
  ('A0.U04.L02', 'A0.U04', '`there is/there are` and local places', 'sentence_builder', 'describe a simple picture/map with 5/6 correct singular/plural there is/are statements and answer 3 location questions.', '["5/6 agreement and three understandable questions."]'::jsonb, 17),
  ('A0.U04.L03', 'A0.U04', '`can/can''t` for ability and polite requests', 'role_play', 'express 3 abilities/inabilities and make 3 understandable requests using can.', '["5/6 correct base-verb forms and requests include an understandable request plus polite marker where suitable."]'::jsonb, 18),
  ('A0.U04.L04', 'A0.U04', 'Ask for help and give simple directions', 'sentence_builder', 'complete a map-based exchange by asking where one place is and giving two-step directions.', '[]'::jsonb, 19),
  ('A0.U05.L01', 'A0.U05', 'Word order, capitals, full stops, and `and/but`', 'sentence_builder', 'arrange 5/6 word sets into simple statements and punctuate 4/5 sentences appropriately.', '["5/6 word orders and 4/5 capitalization/end marks."]'::jsonb, 20),
  ('A0.U05.L02', 'A0.U05', 'Integrated personal-profile workshop', 'sentence_builder', '', '[]'::jsonb, 21),
  ('A0.U05.L03', 'A0.U05', 'Read a message and find the useful details', 'sentence_builder', 'retrieve 4/5 literal details from a short familiar message and identify its practical purpose.', '["4/5 facts and practical purpose."]'::jsonb, 22),
  ('A0.U05.L04', 'A0.U05', 'Write a short connected profile', 'essay_analysis', 'My name is Huda. I am 20. I live in a small city. I have one brother. Our home is near a park. I study in the morning. I go to the library at four.', '[]'::jsonb, 23),
  ('A0.U05.L05', 'A0.U05', 'Retrieval, diagnostic repair, and transition practice', 'sentence_builder', 'retrieve at least one target from each unit and identify one personal review need.', '["complete resources/foundation-assessment.md diagnostic repair check, then final transition gate on a later day. Link results to the specific outcome/lesson; do not average a missed listening skill away with strong writing."]'::jsonb, 24),
  ('A1.U01.L01', 'A1.U01', 'Ask and answer personal questions', 'role_play', 'ask and answer four personal questions using appropriate be or do forms.', '["4/4 questions have correct auxiliaries and the partner can report two answers."]'::jsonb, 1),
  ('A1.U01.L02', 'A1.U01', 'Describe people and relationships', 'sentence_builder', 'Nadia is from Tunis. She is a cook. Her husband works at a school. They have one child. Ask who is a cook and where her husband works.', '["five meaningful sentences; accurate subject-verb agreement in 4/5."]'::jsonb, 2),
  ('A1.U01.L03', 'A1.U01', 'Give and check contact details', 'sentence_builder', 'exchange fictional contact cards; listener reads back the number for confirmation.', '["transcribe all name letters and at least 9/10 digits; accurately ask for clarification."]'::jsonb, 3),
  ('A1.U02.L01', 'A1.U02', 'Describe a home and locate objects', 'sentence_builder', 'partner A describes a room; partner B places four counters on a blank plan and asks one location question.', '["at least 4/5 accurate is/are choices and three understandable location phrases."]'::jsonb, 4),
  ('A1.U02.L02', 'A1.U02', 'Describe routines and frequency', 'sentence_builder', 'describe a weekday routine in six sentences, placing frequency words correctly and using third-person -s in 4/5 target clauses.', '["six relevant sentences, 4/5 verb forms and 4/5 adverb positions."]'::jsonb, 5),
  ('A1.U02.L03', 'A1.U02', 'A routine and a simple invitation', 'sentence_builder', '“Mina starts work at eight. She usually takes the bus, but today she is walking because the bus is late. She has lunch at noon.”', '["answer 3/3 factual questions; produce a present-simple habit and a present-continuous “now/temporary” example; message includes all four required elements. If tense choice is unclear, sort five new statements into “usual” and “happening now”."]'::jsonb, 6),
  ('A1.U03.L01', 'A1.U03', 'Name foods and express preferences', 'sentence_builder', 'ask a partner Do you like ...? and record three answers; report one accurate fact.', '["8/10 food-picture matches and three understandable preference sentences."]'::jsonb, 7),
  ('A1.U03.L02', 'A1.U03', 'Order politely and ask about prices', 'role_play', 'complete a café exchange with an item, quantity, price question, and confirmation.', '["complete four transaction moves, correctly use singular/plural price question."]'::jsonb, 8),
  ('A1.U03.L03', 'A1.U03', 'Ask for quantities and complete a shopping list', 'sentence_builder', 'For lunch, buy a loaf of bread, six eggs, some cheese, and two tomatoes. Ask what is bought and how many eggs.', '["list has five suitable items, two quantities, and four successful exchange turns."]'::jsonb, 9),
  ('A1.U04.L01', 'A1.U04', 'Read a simple timetable', 'sentence_builder', 'retrieve five details from a weekly timetable and ask two schedule questions.', '["4/5 facts and correct auxiliary in both questions."]'::jsonb, 10),
  ('A1.U04.L02', 'A1.U04', 'Say what is happening now', 'sentence_builder', 'contrast routine and current action in six spoken/written sentences, with correct be + -ing in 4/5 clauses.', '["classify 5/6 contexts and form 4/5 continuous clauses."]'::jsonb, 11),
  ('A1.U04.L03', 'A1.U04', 'Write a short schedule message', 'essay_analysis', 'write a 40–60-word schedule message with two activities, two times/days, and one question.', '["40–60 words, required schedule details, readable sentence punctuation, and accurate forms in 4/5 clauses."]'::jsonb, 12),
  ('A1.U05.L01', 'A1.U05', 'Ask for and follow directions', 'sentence_builder', 'each learner gets a different start/destination card and gives directions without pointing.', '["4/5 routes followed accurately."]'::jsonb, 13),
  ('A1.U05.L02', 'A1.U05', 'Ask for a simple service', 'sentence_builder', 'complete a service exchange with a greeting, need, one information question, and a confirmation.', '["all four exchange moves; learner accurately repeats the key time/place."]'::jsonb, 14),
  ('A1.U05.L03', 'A1.U05', 'Understand a public notice', 'sentence_builder', 'CITY LIBRARY: Open Monday–Saturday, 9:00 a.m.–6:00 p.m. Closed Sunday. Please return books at the desk. New members: bring an ID card.', '["4/4 details and one accurate purpose statement."]'::jsonb, 15),
  ('A1.U06.L01', 'A1.U06', 'Talk about hobbies and preferences', 'sentence_builder', 'ask and answer five questions about free-time activities and give one reason.', '["4/5 questions well formed, one reason, and two correct reported facts."]'::jsonb, 16),
  ('A1.U06.L02', 'A1.U06', 'Invite, accept, and decline politely', 'role_play', 'make an invitation, accept or decline, and agree on a day/time/place.', '["include invitation, response, alternative/confirmation; partner can repeat the agreed plan."]'::jsonb, 17),
  ('A1.U06.L03', 'A1.U06', 'Write and relay an invitation', 'essay_analysis', 'Hi Lina, Would you like to see a film on Friday? It starts at six at the City Cinema. We can meet outside at 5:45. Let me know if you can come. — Noor', '["all five details present, 4/5 understandable sentences, relay preserves day/time/place.", "What time does the learner get up?", "How do they go to work?", "What do they do at lunch?", "What do they do in the evening?"]'::jsonb, 18),
  ('A2.U01.L01', 'A2.U01', 'Build a past-time account', 'sentence_builder', 'tell a real or imagined account using these or six learner-created events.', '["at least four accurate past forms and three sequence markers in logical order."]'::jsonb, 1),
  ('A2.U01.L02', 'A2.U01', 'Add a reaction and a reason', 'role_play', 'On Sunday, I took my niece to the science museum. We saw a robot show and made a paper bridge. The museum was busy, but the staff were helpful. I enjoyed the visit because my niece asked many questions.', '["70–90 words, 3 accurate past verbs, one reason and one contrast, clear event order."]'::jsonb, 2),
  ('A2.U01.L03', 'A2.U01', 'A past visit and a future arrangement', 'role_play', '“On Saturday, Huda visited the old market with her cousin. They bought fruit and had lunch at a small café. Huda liked the market because it was lively, although it was crowded. She is going to return next month.”', '["correctly answer all 3 content questions; use two past forms and a clearly marked intention; writing contains the three required features. Review irregular past forms in a fresh sentence if missed."]'::jsonb, 3),
  ('A2.U02.L01', 'A2.U02', 'Plan a journey from a timetable', 'role_play', 'use a second timetable card to plan a trip; ask a partner two questions and repeat the answer to confirm.', '["4/5 details, both questions understandable, no confusion of departure and arrival."]'::jsonb, 4),
  ('A2.U02.L02', 'A2.U02', 'Explain a travel problem and request help', 'role_play', 'Platform 2 is closed. For trains to Hilltown, use platform 4. Ask staff if you need assistance. Which platform? 4. What is closed? Platform 2.', '["problem, request, relevant question, accurate confirmation all present."]'::jsonb, 5),
  ('A2.U02.L03', 'A2.U02', 'Compare accommodation and confirm a booking', 'role_play', 'compare two lodging options and confirm three booking details in a role-play.', '["comparison accurate, all three details repeated, no invented amenities."]'::jsonb, 6),
  ('A2.U03.L01', 'A2.U03', 'Describe symptoms and ask for help', 'role_play', 'use a fictional symptom card to explain problem and duration; partner asks one follow-up.', '["symptom, time, and effect conveyed; partner accurately repeats them."]'::jsonb, 7),
  ('A2.U03.L02', 'A2.U03', 'Give simple advice and understand instructions', 'role_play', 'give two relevant suggestions and follow three short care instructions.', '["3/3 instructions understood and advice form is grammatical/relevant."]'::jsonb, 8),
  ('A2.U03.L03', 'A2.U03', 'Make an appointment and summarize instructions', 'role_play', 'Clinic: appointments Tuesday–Friday. Bring your appointment card. If you cannot attend, call before 9 a.m. Ask available days, what to bring, and when to call if unable to attend.', '["all three details accurate and at least one clarification/confirmation phrase."]'::jsonb, 9),
  ('A2.U04.L01', 'A2.U04', 'Describe duties and schedules', 'role_play', 'describe four work/study duties and compare a weekly schedule using have to accurately.', '["4/5 modal/subject forms; correctly distinguish optional from forbidden."]'::jsonb, 10),
  ('A2.U04.L02', 'A2.U04', 'Give advice and make a request at work', 'role_play', 'The shared printer is out of paper. The report is due at 3 p.m. Ask the office assistant for more paper or use the printer on floor two. What is wrong? printer has no paper. When is report due? 3 p.m. What alternatives are stated? ask assistant/use floor two.', '["relevant suggestion, understandable request, no unsupported “must.”"]'::jsonb, 11),
  ('A2.U04.L03', 'A2.U04', 'Write a practical work message', 'essay_analysis', 'write an 80–100-word work/study message with a problem, relevant detail, request, and next step.', '["four content elements, appropriate tone, readable sequence."]'::jsonb, 12),
  ('A2.U05.L01', 'A2.U05', 'Explain intentions and arrangements', 'role_play', 'explain a plan, reason, and one arrangement; partner asks when/where.', '["3/4 choices fit context, arrangement details included."]'::jsonb, 13),
  ('A2.U05.L02', 'A2.U05', 'Make predictions and spontaneous offers', 'role_play', 'respond to four situations using a context-appropriate prediction, offer, or intention.', '["3/4 forms fit the supplied context and function is explained."]'::jsonb, 14),
  ('A2.U05.L03', 'A2.U05', 'Negotiate a plan and send a confirmation', 'role_play', 'negotiate a plan, resolve one conflict, and write a 70–90-word confirmation with complete details.', '["no constraint violated, final details repeated accurately, message includes all five elements."]'::jsonb, 15),
  ('A2.U06.L01', 'A2.U06', 'Compare choices using evidence', 'essay_analysis', 'compare two options in four accurate sentences and justify a preference with two details.', '["4/5 comparison forms/facts accurate and reasons support stated preference."]'::jsonb, 16),
  ('A2.U06.L02', 'A2.U06', 'Compare experiences and express preferences', 'role_play', 'Maya prefers the train: it is faster and she can read. Rafi prefers the bus because it is cheaper and stops near his home. Neither travels every day. Ask who values price, who values speed, and whether either goes daily.', '["two accurate comparisons and one respectful follow-up."]'::jsonb, 17),
  ('A2.U06.L03', 'A2.U06', 'Write a short recommendation', 'essay_analysis', 'write a 90–110-word recommendation comparing two familiar choices and acknowledging one trade-off.', '["90–110 words, two supported comparisons, one trade-off, audience-based conclusion.", "Where did the learner go?", "What did they do?", "What was the weather like?", "What is planned for next month?"]'::jsonb, 18),
  ('B1.U01.L01', 'B1.U01', 'Tell a personal story with time order', 'role_play', 'complete: When we ___ (arrive), the museum ___ (already close).', '["at least four correct past forms and a clear chronological order."]'::jsonb, 1),
  ('B1.U01.L02', 'B1.U01', 'Describe change and experience', 'role_play', '“Before I moved to this city, I lived with my parents. I had never worked full-time, and I was nervous at first. Now I feel more confident.” Which idea is the strongest result?', '["one past habit, one contrast, one present result."]'::jsonb, 2),
  ('B1.U01.L03', 'B1.U01', 'Summarize a personal experience', 'role_play', '“I was nervous before the interview. I had prepared my answers, but I still felt unsure. After the first question, I relaxed and spoke more naturally. In the end, I got the job.”', '["reason, steps, outcome, and reflection are all present."]'::jsonb, 3),
  ('B1.U02.L01', 'B1.U02', 'Express an opinion clearly', 'role_play', '“Online learning is flexible, but it can feel isolating. I prefer a mixed model because it combines independence with teacher support.” Which word introduces contrast?', '["3 clear reasons and one contrast or example."]'::jsonb, 4),
  ('B1.U02.L02', 'B1.U02', 'Build a paragraph with reasons and examples', 'essay_analysis', '“I believe students should have more project-based learning. It helps them apply theory to real problems. For example, a class can design a school campaign or a small business plan. This method also improves cooperation. Therefore, it prepares students better for work.”', '["clear topic sentence, at least two reasons, one example, and a closing sentence."]'::jsonb, 5),
  ('B1.U02.L03', 'B1.U02', 'Respond to a counterargument', 'essay_analysis', 'discuss whether school uniforms are a good idea. Partner A argues in favour. Partner B opposes. Switch roles after 90 seconds.', '["one concession, one counterargument, and one justification."]'::jsonb, 6),
  ('B1.U03.L01', 'B1.U03', 'Define the problem and the cause', 'role_play', 'each learner chooses a local issue and explains its cause and one effect.', '["clear problem statement, cause, and effect; no invented evidence."]'::jsonb, 7),
  ('B1.U03.L02', 'B1.U03', 'Recommend a solution and weigh a trade-off', 'role_play', '“The city should test a later bus service for three months and publish the results.” Which part is the recommendation?', '["problem, proposal, reason, trade-off, and conclusion."]'::jsonb, 8),
  ('B1.U03.L03', 'B1.U03', 'Discuss alternatives and choose one', 'role_play', '“Residents say the buses are unreliable at peak times. A dedicated lane could reduce delays, but it would require removing some parking spaces. The city should test the lane for three months and publish the results before deciding whether to expand it.”', '["all members speak, at least one reason and one drawback are named, and the final decision is supported by the group.", "4-point checklist, one point each for clear problem, relevant reason, feasible action, and limitation/result. At least 3/4 plus understandable linking is the local mastery threshold; it is not a CEFR certification."]'::jsonb, 9),
  ('B1.U03.L04', 'B1.U03', 'Explain a problem and recommend a solution', 'role_play', '“Residents say the buses are unreliable at peak times. A dedicated lane could reduce delays, but it would require removing some parking spaces. The city should test the lane for three months and publish the results before deciding whether to expand it.”', '["4-point checklist, one point each for clear problem, relevant reason, feasible action, and limitation/result. At least 3/4 plus understandable linking is the local mastery threshold; it is not a CEFR certification."]'::jsonb, 10),
  ('B1.U04.L01', 'B1.U04', 'Describe responsibilities and routine work', 'role_play', 'choose the correct form: At the moment, I (manage / am managing) a small team.', '["at least three correct verbs and clear time language."]'::jsonb, 11),
  ('B1.U04.L02', 'B1.U04', 'Write a short report or summary', 'essay_analysis', '“The project started late because training was delayed. By week three, the team had completed most of the research, but one department still needed support. The final report recommended clearer deadlines and regular check-ins.” What caused the delay?', '["time order, one cause, one result, and one recommendation."]'::jsonb, 12),
  ('B1.U04.L03', 'B1.U04', 'Explain a difficult situation and a plan', 'role_play', 'manager and employee discuss a delay. Candidate language: We need an updated plan., If we reduce the scope, we can finish on time., By Friday, we should have a revised schedule.', '["plan, timeline, and reason are all clear."]'::jsonb, 13),
  ('B1.U05.L01', 'B1.U05', 'Discuss benefits and drawbacks', 'role_play', '“Many cities encourage cycling. A bike lane reduces congestion and improves health, but it may reduce parking space. The main challenge is that drivers need time to adapt.” What are the benefits?', '["benefit, drawback, and a conclusion."]'::jsonb, 14),
  ('B1.U05.L02', 'B1.U05', 'Write a balanced paragraph', 'essay_analysis', '“Public transport is often cheaper and more sustainable, but many commuters still prefer cars. The main advantage is lower pollution and lower cost. However, cars are often seen as more comfortable and convenient. In my view, better bus services and cleaner stations would reduce the gap.”', '["clear statement, two side points, conclusion, and at least four connectors."]'::jsonb, 15),
  ('B1.U05.L03', 'B1.U05', 'Speak and mediate on a public issue', 'role_play', 'summarize a discussion and relay a position neutrally to another person.', '["the spokesperson restates the recommendation, the reason, and one objection."]'::jsonb, 16),
  ('B1.U06.L01', 'B1.U06', 'Evaluate information and source quality', 'essay_analysis', '“A news site reports that smartphone use among teenagers has increased, but it does not mention how the survey was conducted. A second article includes charts and a clear method, but it covers only one region.” Which is more reliable?', '["at least one claim and one reliability point."]'::jsonb, 17),
  ('B1.U06.L02', 'B1.U06', 'Compare digital and face-to-face learning', 'role_play', 'discuss and justify a preference between two learning modes.', '["contrast, at least two reasons, conclusion."]'::jsonb, 18),
  ('B1.U06.L03', 'B1.U06', 'Write and relay a recommendation about media or technology', 'essay_analysis', 'write a short recommendation about digital habits or online study and relay it clearly to another person.', '["issue, action, reason, and conclusion.", "What is the problem described?", "Why do people still prefer cars?", "What is the proposed solution?", "What is the writer’s opinion?"]'::jsonb, 19),
  ('B2.U01.L01', 'B2.U01', 'Identify a claim and weigh the evidence', 'essay_analysis', '“A city tested a slower school-start schedule for one term. Attendance improved and students reported lower stress. The pilot had 120 students and no comparison group.” Which word shows measurement?', '["claim, evidence, and one limit are all named."]'::jsonb, 1),
  ('B2.U01.L02', 'B2.U01', 'Build a structured argument with cautious language', 'essay_analysis', '“The new policy may improve student well-being, although the pilot was limited to one school. The survey showed that absenteeism fell and students reported better focus. However, the sample was small, so the results should be treated cautiously. Overall, the policy deserves a longer trial before a wider rollout.”', '["thesis, evidence, one limitation, one counterargument, and a conclusion."]'::jsonb, 2),
  ('B2.U01.L03', 'B2.U01', 'Respond to a counterargument and refine a position', 'essay_analysis', 'debate whether a school should introduce a longer lunch break or a four-day week. Each learner states a claim plus a counterargument and response.', '["counterargument and response are clearly marked, and the final stance remains consistent.", "score 0–2 each for evidence use, qualification, organization, and response to counterargument. Success for this workshop: 6/8 with no invented evidence. This local criterion is not a CEFR score."]'::jsonb, 3),
  ('B2.U01.L04', 'B2.U01', 'Weigh evidence and qualify an argument', 'essay_analysis', '“A college trialled a four-day teaching week in one department. Attendance rose slightly, and students reported more time for independent study. The trial lasted six weeks and included 42 volunteers. These results are promising, but they do not establish that the schedule would work across the whole college.”', '["score 0–2 each for evidence use, qualification, organization, and response to counterargument. Success for this workshop: 6/8 with no invented evidence. This local criterion is not a CEFR score."]'::jsonb, 4),
  ('B2.U02.L01', 'B2.U02', 'Analyze a media claim', 'essay_analysis', '“A local campaign claims that a new shopping district will create jobs and improve the city center. The article uses interviews with business owners and optimistic language, but no independent figures are provided.” What is the claim?', '["claim, evidence, and one tone or bias note."]'::jsonb, 5),
  ('B2.U02.L02', 'B2.U02', 'Evaluate bias and audience appeal', 'essay_analysis', '“The campaign video presents the new policy as a safe and necessary step for families. It uses images of children and quiet streets, but it does not mention the cost or the disruption during the building phase.” What does the video emphasize?', '["one claim, one method of persuasion, and one missing fact."]'::jsonb, 6),
  ('B2.U02.L03', 'B2.U02', 'Respond to a claim in a formal discussion', 'essay_analysis', 'answer a media or policy claim politely but clearly, with a reason and a counterexample.', '["claim + evidence + response to counterargument."]'::jsonb, 7),
  ('B2.U03.L01', 'B2.U03', 'Discuss social and educational inequality', 'role_play', '“School transport is often unreliable in rural areas, which limits attendance and lowers opportunities for students who need extra support. A small grant for transport could increase access, but it would require local funding and oversight.” What is the problem?', '["problem, cause, and response all present."]'::jsonb, 8),
  ('B2.U03.L02', 'B2.U03', 'Write a balanced policy paragraph', 'essay_analysis', '“A more flexible school timetable could improve wellbeing, yet it could also create timetable pressure for teachers and families.” Use comparison and nuance rather than a single extreme statement.', '["all four parts appear and the position is justified with examples."]'::jsonb, 9),
  ('B2.U03.L03', 'B2.U03', 'Present and mediate a policy recommendation', 'role_play', 'propose one reform for a public issue. Each group prepares a 1-minute summary and then relays it to another group.', '["clarity, evidence, and concession."]'::jsonb, 10),
  ('B2.U04.L01', 'B2.U04', 'Explain a business or leadership issue', 'role_play', '“A company reduced support staff to save costs, but the result was slower customer response and higher employee stress. Managers argued that the policy was temporary. Staff questioned whether it was sustainable.” Which term indicates a concern about long-term viability?', '["cause, effect, and one proposed solution."]'::jsonb, 11),
  ('B2.U04.L02', 'B2.U04', 'Write a brief recommendation for a policy or strategy', 'essay_analysis', 'complete A limited pilot is useful because ____ .', '["clear recommendation, at least two risks or safeguards, and a final decision."]'::jsonb, 12),
  ('B2.U04.L03', 'B2.U04', 'Deliver a short presentation and answer questions', 'role_play', 'present a workplace or environmental recommendation to a small group.', '["clear structure, audience awareness, and response to at least one follow-up question."]'::jsonb, 13),
  ('B2.U05.L01', 'B2.U05', 'Discuss evidence in health and science communication', 'essay_analysis', '“A small study reported that a daily breathing exercise reduced stress in a sample of 30 adults. The report noted that results may be linked to motivation and self-selection, and it did not compare the exercise with other treatments.” What can be concluded?', '["explicit caution and one valid limit."]'::jsonb, 14),
  ('B2.U05.L02', 'B2.U05', 'Present a recommendation with conditions', 'role_play', '“If the trial continues to show lower stress and no adverse side effects, ___ .”', '["recommendation, condition, risk/safeguard, and mention of evidence."]'::jsonb, 15),
  ('B2.U05.L03', 'B2.U05', 'Explain uncertainty and respond to a challenge', 'role_play', 'answer a challenge to a recommendation by acknowledging uncertainty and explaining the next evidence needed.', '["evidence, challenge response, and next evidence needed."]'::jsonb, 16),
  ('B2.U06.L01', 'B2.U06', 'Express a nuanced opinion on identity or culture', 'role_play', '“Cultural exchange programmes can broaden understanding and improve young people’s confidence in communication, although some students still find local customs difficult to interpret. The main challenge is not opposition, but misunderstanding.” What is the central tension?', '["balanced view, at least one reason, and one respectful concession."]'::jsonb, 17),
  ('B2.U06.L02', 'B2.U06', 'Write a formal opinion essay', 'essay_analysis', 'write a 250–300-word essay on a global or cultural issue, using thesis, supporting points, and a counterargument.', '["introduction, evidence, at least one counterargument, and conclusion."]'::jsonb, 18),
  ('B2.U06.L03', 'B2.U06', 'Debate and clarify a position', 'role_play', 'take part in a formal group discussion, respond to disagreement, and summarize the final decision.', '["clear claim, respectful challenge response, and summary of final position.", "What is the main claim?", "Why does the writer say face-to-face teaching still matters?", "What does the final sentence suggest about the best model?"]'::jsonb, 19),
  ('C1.U01.L01', 'C1.U01', 'Map an argument', 'essay_analysis', 'label a passage''s claim, evidence, qualification, and conclusion, each with a text cue.', '["all four functions are located and the qualification is not mistaken for a refutation."]'::jsonb, 1),
  ('C1.U01.L02', 'C1.U01', 'Follow cohesion and scope', 'essay_analysis', 'trace two reference or connective links and identify the scope of a claim.', '["both links are accurate and no broader population or causal claim is invented."]'::jsonb, 2),
  ('C1.U01.L03', 'C1.U01', 'Write an analytical summary', 'essay_analysis', 'write a 70–90-word summary retaining evidence, limitation, and implication.', '["includes all three required relations and makes no unsupported causal claim.", "C1-T-U01 transfer."]'::jsonb, 3),
  ('C1.U02.L01', 'C1.U02', 'Plan for a decision reader', 'essay_analysis', 'organize a report note around a decision question, evidence, limitation, recommendation, and next check.', '["all five functions appear in a logical order and the recommendation remains limited."]'::jsonb, 4),
  ('C1.U02.L02', 'C1.U02', 'Edit agency and register', 'sentence_builder', 'revise nominalized or passive wording when it hides a relevant actor, without making the tone less professional.', '["actor and meaning are preserved; tone is direct, not inflated.", "C1-T-U02 language item."]'::jsonb, 5),
  ('C1.U02.L03', 'C1.U02', 'Draft an evidence-based note', 'essay_analysis', 'produce a 70–100-word manager note including evidence, limitation, and action.', '["all three elements are present and the guide is not credited with an effect that may also come from demonstrations.", "C1-T-U02 transfer."]'::jsonb, 6),
  ('C1.U03.L01', 'C1.U03', 'Build a spoken argument map', 'essay_analysis', 'plan a short talk with claim, evidence, limitation, and decision rule.', '["no evidence point is used to prove an unmeasured outcome."]'::jsonb, 7),
  ('C1.U03.L02', 'C1.U03', 'Make relations audible', 'essay_analysis', 'use signposting and pausing to make two reasoning relations clear in a spoken explanation.', '["listener identifies the intended relation without seeing the notes."]'::jsonb, 8),
  ('C1.U03.L03', 'C1.U03', 'Respond and repair', 'role_play', 'answer a challenge question relevantly and clarify one ambiguous term.', '["direct response, accurate qualification, and successful clarification/repair.", "C1-T-U03 transfer."]'::jsonb, 9),
  ('C1.U04.L01', 'C1.U04', 'Infer stance from cues', 'essay_analysis', 'support a stance inference with two wording/context cues and label it as inference.', '["two cues cited; no inferred emotion is stated as fact."]'::jsonb, 10),
  ('C1.U04.L02', 'C1.U04', 'Interpret irony cautiously', 'essay_analysis', 'compare a literal and a plausible ironic reading and state what remains uncertain.', '["the challenge is recognized while hostility/sarcasm is not assumed."]'::jsonb, 11),
  ('C1.U04.L03', 'C1.U04', 'Paraphrase implication', 'essay_analysis', 'produce a neutral paraphrase and a clearly labeled inference from the same input.', '["explicit content and inference remain distinct and cue-supported.", "C1-T-U04 transfer."]'::jsonb, 12),
  ('C1.U05.L01', 'C1.U05', 'Compare methods and constructs', 'essay_analysis', 'state what two sources measure and whether they support a common outcome claim.', '["no learning-effect claim is inferred from preference or tutor views alone."]'::jsonb, 13),
  ('C1.U05.L02', 'C1.U05', 'Synthesize sources and communicate uncertainty', 'essay_analysis', 'read aloud: “Both reports suggest that schedule flexibility affects people differently. One emphasizes commute experience; the other highlights coordination. A policy may therefore need a shared collaboration window, but the evidence does not establish a single best arrangement.”', '["0–2 each for accurate attribution, synthesis, qualification, and audience clarity. Success: 6/8 and no misrepresentation. Teacher checks paraphrase and language use.", "name one focus of each report and the policy implication."]'::jsonb, 14),
  ('C1.U05.L03', 'C1.U05', 'Synthesize and qualify', 'essay_analysis', 'write a 70–100-word synthesis that attributes both sources, identifies one shared theme and one difference, and proposes no unsupported conclusion.', '["attribution and distinction are accurate; no causal outcome is invented.", "C1-T-U05 transfer."]'::jsonb, 15),
  ('C1.U06.L01', 'C1.U06', 'Listen for interests', 'essay_analysis', 'distinguish a stakeholder''s stated position from the interest or constraint it may represent.', '["label proposals as proposals and do not assign motives as facts."]'::jsonb, 16),
  ('C1.U06.L02', 'C1.U06', 'Negotiate conditional options', 'role_play', 'formulate an option with a clear condition and confirm whether it is accepted.', '["every condition is retained and no discussion is reported as consensus."]'::jsonb, 17),
  ('C1.U06.L03', 'C1.U06', 'Mediate the decision', 'role_play', 'relay the decision and one unresolved issue to a new audience without altering either.', '["condition, common ground, and unresolved matter are all accurately represented.", "C1-T-U06 transfer."]'::jsonb, 18),
  ('C2.U01.L01', 'C2.U01', 'Choose precise words in context', 'essay_analysis', 'distinguish the contextual force of four near-synonyms and justify a choice with the source''s communicative purpose.', '["wording preserves observation and causal limit."]'::jsonb, 1),
  ('C2.U01.L02', 'C2.U01', 'Edit commitment and focus', 'essay_analysis', 'revise a short passage without changing date, quantity, condition, scope, or modality.', '["all factual commitments remain stable.", "C2-T-U01 language item."]'::jsonb, 2),
  ('C2.U01.L03', 'C2.U01', 'Adapt two audience versions', 'essay_analysis', 'produce two audience-specific versions and explain one deliberate change that does not alter the evidence.', '["both versions preserve the provisional decision and the missing causal evidence.", "C2-T-U01 transfer."]'::jsonb, 3),
  ('C2.U02.L01', 'C2.U02', 'Reconstruct premises', 'essay_analysis', 'distinguish explicit proposition, presupposition, entailment, and defeasible implication in a dense short argument.', '["categories are correctly assigned and supported by wording."]'::jsonb, 4),
  ('C2.U02.L02', 'C2.U02', 'Rank competing readings', 'essay_analysis', 'rank three interpretations by textual support and explain why one plausible claim is unsupported.', '["strongest reading is supported; contradiction and absence of evidence are distinguished."]'::jsonb, 5),
  ('C2.U02.L03', 'C2.U02', 'Write interpretive commentary', 'essay_analysis', 'write a 120–160-word commentary separating explicit content, inference, and unknown, with an alternative interpretation.', '["every interpretive claim cites a cue and at least one plausible alternative is acknowledged.", "C2-T-U02 transfer."]'::jsonb, 6),
  ('C2.U03.L01', 'C2.U03', 'Shape an address for an audience', 'essay_analysis', 'organize an address with a claim, progression, and close suited to a stated audience.', '["audience can restate the recommendation without mistaking it for cancellation."]'::jsonb, 7),
  ('C2.U03.L02', 'C2.U03', 'Control parallelism and emphasis', 'essay_analysis', 'use one parallel contrast to sharpen a distinction without exaggerating evidence.', '["wording is parallel and the listener identifies output versus outcome."]'::jsonb, 8),
  ('C2.U03.L03', 'C2.U03', 'Answer adversarial questions', 'role_play', 'answer two challenging questions by acknowledging their premise, addressing evidence or values, and preserving qualifications.', '["direct response, evidence boundary, and one useful clarification/repair are observable.", "C2-T-U03 transfer."]'::jsonb, 9),
  ('C2.U04.L01', 'C2.U04', 'Map authority, interests, and unknowns', 'essay_analysis', 'record each stakeholder''s position, condition, authority, and unknown before negotiation.', '["preferences are not presented as commitments, and scope is accurate."]'::jsonb, 10),
  ('C2.U04.L02', 'C2.U04', 'Make a high-stakes recommendation with precision', 'essay_analysis', '“Operations supports a pilot if weekend data are collected. Finance prefers a cap on overtime. The service lead says any cap must not leave the busiest shift uncovered. No team has yet estimated the effect on customer satisfaction.”', '["0–2 each for factual fidelity, explicit uncertainty, workable safeguards, and concise register. Success: 6/8 with no invented facts; specialist review is required for actual operational decisions.", "state one condition from each function and one missing measure."]'::jsonb, 11),
  ('C2.U04.L03', 'C2.U04', 'Write and verify a decision record', 'essay_analysis', 'produce a concise record that names decision, actor, condition, owner, measure, review date, and unresolved issue.', '["a reader can identify exactly what was authorized and what was not.", "C2-T-U04 transfer."]'::jsonb, 12),
  ('C2.U05.L01', 'C2.U05', 'Audit the claim chain', 'essay_analysis', 'trace a report''s evidence, alternative explanation, limit, and recommendation.', '["staffing is not named as the sole cause."]'::jsonb, 13),
  ('C2.U05.L02', 'C2.U05', 'Revise information focus and rhythm', 'essay_analysis', 'revise sentence order and rhythm to foreground the decision boundary without changing claim strength.', '["focus improves while scope and qualification remain unchanged."]'::jsonb, 14),
  ('C2.U05.L03', 'C2.U05', 'Edit for fidelity and concision', 'essay_analysis', 'produce a 180–230-word evidence-based note and a revision note explaining an improvement that preserves meaning.', '["no invented evidence, exact causal limit, and a defensible audience choice.", "C2-T-U05 transfer."]'::jsonb, 15)
insert into public.lessons (id, unit_id, title, lesson_type, scenario, assessment, sort_order) values
  ('C2.U06.L01', 'C2.U06', 'Track exact commitments', 'essay_analysis', 'distinguish a stated commitment, conditional plan, opinion, and inference in conflicting accounts.', '["no one is reported as saying analysis is complete."]'::jsonb, 16),
  ('C2.U06.L02', 'C2.U06', 'Test and repair understanding', 'role_play', 'ask a clarification question that tests scope or deadline and reformulate a partner''s position for confirmation.', '["ambiguity is surfaced and correction incorporated."]'::jsonb, 17),
  ('C2.U06.L03', 'C2.U06', 'Mediate for two audiences', 'role_play', 'create specialist and public summaries that preserve the same condition and uncertainty.', '["both accounts preserve the completeness condition and do not call Friday unconditional.", "C2-T-U06 transfer."]'::jsonb, 18),
  ('POST-C2.T01.L01', 'POST-C2.T01', 'Read a study as an argument', 'essay_analysis', 'label the sample, measure, and missing outcome in the example;', '["all six abstract elements are located or explicitly marked “not reported”; the proposed overclaim is justified with a textual cue."]'::jsonb, 1),
  ('POST-C2.T01.L02', 'POST-C2.T01', 'Synthesize sources and qualify a claim', 'essay_analysis', 'write 120–160 words that answers a question selected by the teacher, attributes both sources, names one shared theme and one difference, and identifies the evidence gap.', '["both sources and their measures are accurately distinguished; the synthesis does not invent causation."]'::jsonb, 2),
  ('POST-C2.T01.L03', 'POST-C2.T01', 'Write and present a research brief', 'essay_analysis', '“The pilot survey found a preference among respondents for the revised rota (Lee, 2024). Because participation was voluntary and no absence data were collected, the result should not be read as evidence of improved attendance.” The citation here is a fictional classroom placeholder, not a real source.', '["required sections are present; every external claim is attributable; limitations constrain the implication; oral answer responds to the actual question."]'::jsonb, 3),
  ('POST-C2.T02.L01', 'POST-C2.T02', 'Frame a decision brief', 'essay_analysis', 'convert a one-page fictional scenario into a 150-word decision brief.', '["decision, evidence, risk, owner, date, and unknown are not conflated."]'::jsonb, 4),
  ('POST-C2.T02.L02', 'POST-C2.T02', 'Listen, clarify, and negotiate constraints', 'role_play', 'take notes under CONDITION / LIMIT / REQUEST / UNKNOWN and compare with the key.', '["all four script details are retained, questions resolve an ambiguity, and the final agreement names owner/date/condition."]'::jsonb, 5),
  ('POST-C2.T02.L03', 'POST-C2.T02', 'Deliver difficult news and document action', 'role_play', '“The launch is moving from 12 to 19 May because the accessibility review is not complete. The new date is confirmed. We will send the revised test schedule by Wednesday; please contact the project lead if the change creates a delivery risk.” The reason and dates are fictional.', '["change/reason/impact/next step are explicit, claims match the scenario, and the response acknowledges the concern."]'::jsonb, 6),
  ('POST-C2.T03.L01', 'POST-C2.T03', 'Editorial and translation review', 'essay_analysis', 'partner reads the source passage aloud twice. The reviewer listens without looking at the text.', '["compare source and revision for preserved propositions, date, commitment strength, tone, and readability. Use a short commentary to justify each substantive change. There is no single correct rewrite; score the reasoning against these criteria.", "state the release date and commitment strength."]'::jsonb, 7),
  ('POST-C2.T03.L02', 'POST-C2.T03', 'Diagnose before rewriting', 'essay_analysis', 'mark a supplied 250-word draft with queries, not guesses, and sort edits into meaning / structure / style.', '["each proposed change has an identified problem and does not add facts."]'::jsonb, 8),
  ('POST-C2.T03.L03', 'POST-C2.T03', 'Edit for flow, register, and fidelity', 'essay_analysis', 'edit a new 180–250-word notice for two audiences; provide a change log with three consequential edits and one query.', '["meaning and commitment are stable, both registers suit their readers, and each rationale points to evidence in the source."]'::jsonb, 9),
  ('POST-C2.T04.L01', 'POST-C2.T04', 'Build an argument listeners can follow', 'essay_analysis', 'prepare a 3–4-minute argument from a new evidence card.', '["each claim has a source or is labeled as a proposal; the decision follows from stated evidence and limits."]'::jsonb, 10),
  ('POST-C2.T04.L02', 'POST-C2.T04', 'Handle questions and chair disagreement', 'role_play', 'deliver an argument and respond to one evidence challenge and one value-based objection; chair a partner exchange and summarize both positions.', '["answer is relevant, uncertainty is retained, and each position is recognizable to its speaker."]'::jsonb, 11),
  ('POST-C2.T04.L03', 'POST-C2.T04', 'Rehearse delivery and adapt to audience', 'essay_analysis', 'compare the specialist phrase “comparative utilization data” with “how many people use the service compared with before.” Both can be suitable; choose for audience and define the measure.', '["both versions retain the same claim, limit, and decision; the explanation fits the audience."]'::jsonb, 12),
  ('POST-C2.T05.L01', 'POST-C2.T05', 'Analyze the source before translating', 'essay_analysis', 'complete a source brief for a short notice and flag one phrase requiring author clarification.', '["proposition, time, condition, and commitment are captured separately."]'::jsonb, 13),
  ('POST-C2.T05.L02', 'POST-C2.T05', 'Compare translations and mediate meaning', 'essay_analysis', 'compare two learner-generated translations of a new source, note the audience, and explain one alternative.', '["comparison cites specific wording and distinguishes source facts from translator inference."]'::jsonb, 14),
  ('POST-C2.T05.L03', 'POST-C2.T05', 'Revise translation and explain uncertainty', 'essay_analysis', 'translate a 100–140-word fictional public notice, add a 60-word translator’s note, and orally brief a non-specialist.', '["key facts and commitments are retained; at least one real ambiguity is responsibly handled; choices suit the stated readership."]'::jsonb, 15),
  ('POST-C2.T06.L01', 'POST-C2.T06', 'Trace framing and agency', 'essay_analysis', 'annotate a short public statement for actors, verbs, evaluative terms, and omissions; separate observation from inference in two columns.', '["every inference cites a linguistic cue and an alternative explanation is considered."]'::jsonb, 16),
  ('POST-C2.T06.L02', 'POST-C2.T06', 'Analyze stance, implicature, and audience', 'essay_analysis', 'analyze a short excerpt with its speaker/audience/context card and identify two plausible readings plus discriminating evidence.', '["explicit wording and inference are separated; no emotion is asserted as fact without cues."]'::jsonb, 17),
  ('POST-C2.T06.L03', 'POST-C2.T06', 'Evaluate rhetorical effects and write an analysis', 'essay_analysis', '“We counted the forms processed, not the cases resolved.” The parallel construction makes the measure distinction salient; it does not prove either number is high or low. A defensible analysis states the feature, textual cue, possible effect, and limit.', '["three observations have quoted cues, inferences are qualified, context is used, and one alternative reading is fairly represented."]'::jsonb, 18)
insert into public.flashcards (id, lesson_id, question, answer, phonetic, audio_url) values
  ('PRE-A0.U01.L01-FC01', 'PRE-A0.U01.L01', 'What is the goal of “Recognize the alphabet”?', 'correctly identify 20/26 uppercase letters in a mixed set and match at least 18 to their lowercase forms.', '', null),
  ('PRE-A0.U01.L02-FC01', 'PRE-A0.U01.L02', 'What is the goal of “Match uppercase and lowercase”?', 'match 24/26 case pairs without relying on alphabet order.', '', null),
  ('PRE-A0.U01.L03-FC01', 'PRE-A0.U01.L03', 'What is the goal of “Say letter names; do not confuse names with sounds”?', 'name 20/26 shown letters and select the spoken letter name when it is said aloud.', '', null),
  ('PRE-A0.U01.L04-FC01', 'PRE-A0.U01.L04', 'What is the goal of “Write recognizable letter forms”?', 'form at least 20 lowercase and 20 uppercase letters so a reader can identify them.', '', null),
  ('PRE-A0.U02.L01-FC01', 'PRE-A0.U02.L01', 'What is the goal of “Vowels, consonants, and speech sounds”?', 'identify the five vowel letters and classify the other 21 letters as consonant letters; identify the first sound in 4/5 taught words.', '', null),
  ('PRE-A0.U02.L02-FC01', 'PRE-A0.U02.L02', 'What is the goal of “Hear and find first, middle, and last sounds”?', 'identify the first and last sounds in 4/5 familiar words and the short vowel sound in 3/4 spoken CVC words.', '', null),
  ('PRE-A0.U02.L03-FC01', 'PRE-A0.U02.L03', 'What is the goal of “Contrast sounds without guessing from letter names”?', 'distinguish at least 4/5 teacher-spoken contrasts from the taught set, using picture or word cards.', '', null),
  ('PRE-A0.U02.L04-FC01', 'PRE-A0.U02.L04', 'What is the goal of “Short-vowel CVC patterns”?', 'blend and read 8/10 taught CVC words with short a, e, i, o, u.', '', null),
  ('PRE-A0.U03.L01-FC01', 'PRE-A0.U03.L01', 'What is the goal of “Blend, segment, and change one sound”?', 'read 8/10 taught CVC words and spell 4/5 from oral dictation using sound-to-letter mapping.', '', null),
  ('PRE-A0.U03.L02-FC01', 'PRE-A0.U03.L02', 'What is the goal of “Word families, rhyme, and syllables”?', 'identify a rhyming word for 4/5 spoken prompts and clap the syllables in 4/5 familiar words.', '', null),
  ('PRE-A0.U03.L03-FC01', 'PRE-A0.U03.L03', 'What is the goal of “Common consonant teams: `sh`, `ch`, `th`, `ck`”?', 'recognize sh, ch, and ck in taught words and decode 6/8 taught words.', '', null),
  ('PRE-A0.U03.L04-FC01', 'PRE-A0.U03.L04', 'What is the goal of “Silent `e` as a useful pattern”?', 'distinguish four taught short-vowel/e word pairs by listening and match each written word to its spoken form.', '', null),
  ('PRE-A0.U04.L01-FC01', 'PRE-A0.U04.L01', 'What is the goal of “Copy letters, labels, and word spaces”?', 'copy 8/10 familiar labels legibly and identify the word boundary in 4/5 short phrases.', '', null),
  ('PRE-A0.U04.L02-FC01', 'PRE-A0.U04.L02', 'What is the goal of “Spell and retrieve familiar words”?', 'spell 8/10 familiar words from picture, oral cue, or real object.', '', null),
  ('PRE-A0.U04.L03-FC01', 'PRE-A0.U04.L03', 'What is the goal of “Read familiar signs and instructions”?', 'read and follow 4/5 familiar printed one-step instructions, follow 4/5 spoken instructions, and match 4/5 classroom labels to objects.', '', null),
  ('PRE-A0.U05.L01-FC01', 'PRE-A0.U05.L01', 'What is the goal of “Greetings and names”?', 'complete a two-turn greeting and state a name in an understandable phrase.', '', null),
  ('PRE-A0.U05.L02-FC01', 'PRE-A0.U05.L02', 'Which begins with the sound /s/?', 'cat; sun', '', null),
  ('PRE-A0.U05.L02-FC02', 'PRE-A0.U05.L02', 'What was the final instruction?', 'cat; M; sit down', '', null),
  ('PRE-A0.U05.L03-FC01', 'PRE-A0.U05.L03', 'What is the goal of “Review and learner self-check”?', 'retrieve one letter, one sound, one word, one instruction, and one greeting without a model.', '', null),
  ('PRE-A0.U05.L04-FC01', 'PRE-A0.U05.L04', 'What is the goal of “Integrated sound, word, and classroom check”?', 'use taught letters, decode taught words, understand instructions, and exchange names.', '', null),
  ('A0.U01.L01-FC01', 'A0.U01.L01', 'What is the goal of “Subject pronouns and `be`”?', 'complete 8/10 sentence prompts with the correct subject pronoun and present be.', '', null),
  ('A0.U01.L02-FC01', 'A0.U01.L02', 'What is the goal of “Affirmative, negative, and `be` questions”?', 'turn 4/5 statements into accurate negatives and 4/5 into appropriate be questions.', '', null),
  ('A0.U01.L03-FC01', 'A0.U01.L03', 'What is the goal of “Numbers, age, and spelling personal details”?', 'identify, say, and write 18/20 numbers from 1–20 and the taught tens; state age using a complete phrase.', '', null),
  ('A0.U01.L04-FC01', 'A0.U01.L04', 'What is her brother?', 'Rabat; one; a student', '', null),
  ('A0.U01.L04-FC02', 'A0.U01.L04', 'How many sisters does he have?', 'twenty; Tunis; two', '', null),
  ('A0.U01.L05-FC01', 'A0.U01.L05', 'What is the goal of “Days, months, dates, and birthdays”?', 'sequence days and months, understand 4/5 read dates, and say or write a personal date using an appropriate preposition.', '', null),
  ('A0.U02.L01-FC01', 'A0.U02.L01', 'What is the goal of “Family and basic plural nouns”?', 'identify 10 family words and form the plural of 8/10 taught regular nouns.', '', null),
  ('A0.U02.L02-FC01', 'A0.U02.L02', 'What is the goal of “`a/an`, `the`, and familiar objects”?', 'choose a suitable article in 8/10 familiar noun phrases and identify when the object is already known.', '', null),
  ('A0.U02.L03-FC01', 'A0.U02.L03', 'What is the goal of “Basic adjectives and describing objects”?', 'produce five noun phrases with a correct simple adjective-before-noun order and matching be sentence.', '', null),
  ('A0.U02.L04-FC01', 'A0.U02.L04', 'What is the goal of “Possessive adjectives, `have/has`, and `’s`”?', 'use four possessive adjectives and have/has in 8/10 descriptions; identify ownership with a name + ''s.', '', null),
  ('A0.U02.L05-FC01', 'A0.U02.L05', 'What color is the door?', 'Hana''s; two; at home; blue', '', null),
  ('A0.U03.L01-FC01', 'A0.U03.L01', 'What is the goal of “Clock time and time prepositions”?', 'identify 8/10 full-hour/half-hour clock times and choose at/on/in in 8/10 taught time phrases.', '', null),
  ('A0.U03.L02-FC01', 'A0.U03.L02', 'What is the goal of “Everyday verbs and present-simple statements”?', 'produce 6/7 short present-simple routine sentences with a subject and correct base/third-person verb form.', '', null),
  ('A0.U03.L03-FC01', 'A0.U03.L03', 'What is the goal of “Frequency words and negative routines”?', 'place always, usually, sometimes, and never appropriately in 4/5 sentences and form 4/5 present-simple negatives.', '', null),
  ('A0.U03.L04-FC01', 'A0.U03.L04', 'What is the goal of “`Do/does` questions and short answers”?', 'ask 4/5 present-simple questions with correct order and give a matching short answer.', '', null),
  ('A0.U03.L05-FC01', 'A0.U03.L05', 'What is the goal of “Read a simple timetable and report a routine”?', 'retrieve 4/5 timetable facts and give a short oral routine with three time phrases.', '', null),
  ('A0.U04.L01-FC01', 'A0.U04.L01', 'What is the goal of “Prepositions of place”?', 'describe 5/6 object locations using a taught preposition.', '', null),
  ('A0.U04.L02-FC01', 'A0.U04.L02', 'What is the goal of “`there is/there are` and local places”?', 'describe a simple picture/map with 5/6 correct singular/plural there is/are statements and answer 3 location questions.', '', null),
  ('A0.U04.L03-FC01', 'A0.U04.L03', 'What is the goal of “`can/can''t` for ability and polite requests”?', 'express 3 abilities/inabilities and make 3 understandable requests using can.', '', null),
  ('A0.U04.L04-FC01', 'A0.U04.L04', 'What is the goal of “Ask for help and give simple directions”?', 'complete a map-based exchange by asking where one place is and giving two-step directions.', '', null),
  ('A0.U05.L01-FC01', 'A0.U05.L01', 'What is the goal of “Word order, capitals, full stops, and `and/but`”?', 'arrange 5/6 word sets into simple statements and punctuate 4/5 sentences appropriately.', '', null),
  ('A0.U05.L03-FC01', 'A0.U05.L03', 'What color is the book?', 'Lina; at the library; four o''clock; Lina''s book; blue', '', null),
  ('A0.U05.L04-FC01', 'A0.U05.L04', 'What is the goal of “Write a short connected profile”?', 'write 6–8 connected sentences about self, family, home, or routine, including at least one be, one have/has, and two routine/location details.', '', null),
  ('A0.U05.L05-FC01', 'A0.U05.L05', 'What is the goal of “Retrieval, diagnostic repair, and transition practice”?', 'retrieve at least one target from each unit and identify one personal review need.', '', null),
  ('A1.U01.L01-FC01', 'A1.U01.L01', 'Where are you from?', 'I''m from Rabat', '', null),
  ('A1.U01.L01-FC02', 'A1.U01.L01', 'Where do you work?', 'I work at a hotel', '', null),
  ('A1.U01.L02-FC01', 'A1.U01.L02', 'What is the goal of “Describe people and relationships”?', 'write and say five accurate sentences about two people using family/job words and be, have, and present-simple verbs.', '', null),
  ('A1.U01.L03-FC01', 'A1.U01.L03', 'What is the goal of “Give and check contact details”?', 'understand and exchange a name, phone number, and email address, asking for repetition once when needed.', '', null),
  ('A1.U02.L01-FC01', 'A1.U02.L01', 'What is the goal of “Describe a home and locate objects”?', 'describe a room in five sentences using there is/are and three place phrases.', '', null),
  ('A1.U02.L02-FC01', 'A1.U02.L02', 'What is the goal of “Describe routines and frequency”?', 'describe a weekday routine in six sentences, placing frequency words correctly and using third-person -s in 4/5 target clauses.', '', null),
  ('A1.U02.L03-FC01', 'A1.U02.L03', 'Why is she walking today?', 'eight; the bus; the bus is late', '', null),
  ('A1.U02.L03-FC02', 'A1.U02.L03', 'Why are they arriving earlier this week?', 'in a bookshop; nine; they are helping with a new display', '', null),
  ('A1.U03.L01-FC01', 'A1.U03.L01', 'What is the goal of “Name foods and express preferences”?', 'name eight foods and state three preferences using like/don''t like and a reason.', '', null),
  ('A1.U03.L02-FC01', 'A1.U03.L02', 'What is the goal of “Order politely and ask about prices”?', 'complete a café exchange with an item, quantity, price question, and confirmation.', '', null),
  ('A1.U03.L03-FC01', 'A1.U03.L03', 'What is the goal of “Ask for quantities and complete a shopping list”?', 'understand a short shopping list and request at least four items using containers or quantities.', '', null),
  ('A1.U04.L01-FC01', 'A1.U04.L01', 'What is the goal of “Read a simple timetable”?', 'retrieve five details from a weekly timetable and ask two schedule questions.', '', null),
  ('A1.U04.L02-FC01', 'A1.U04.L02', 'What is the goal of “Say what is happening now”?', 'contrast routine and current action in six spoken/written sentences, with correct be + -ing in 4/5 clauses.', '', null),
  ('A1.U04.L03-FC01', 'A1.U04.L03', 'What is the goal of “Write a short schedule message”?', 'write a 40–60-word schedule message with two activities, two times/days, and one question.', '', null),
  ('A1.U05.L01-FC01', 'A1.U05.L01', 'What is the goal of “Ask for and follow directions”?', 'ask where a place is and follow a two-step route on a simple map.', '', null),
  ('A1.U05.L02-FC01', 'A1.U05.L02', 'What is the goal of “Ask for a simple service”?', 'complete a service exchange with a greeting, need, one information question, and a confirmation.', '', null),
  ('A1.U05.L03-FC01', 'A1.U05.L03', 'What is the goal of “Understand a public notice”?', 'identify purpose and three details in a short familiar notice.', '', null),
  ('A1.U06.L01-FC01', 'A1.U06.L01', 'What is the goal of “Talk about hobbies and preferences”?', 'ask and answer five questions about free-time activities and give one reason.', '', null),
  ('A1.U06.L02-FC01', 'A1.U06.L02', 'What is the goal of “Invite, accept, and decline politely”?', 'make an invitation, accept or decline, and agree on a day/time/place.', '', null),
  ('A1.U06.L03-FC01', 'A1.U06.L03', 'What time does the learner get up?', 'How do they go to work', '', null),
  ('A1.U06.L03-FC02', 'A1.U06.L03', 'What do they do at lunch?', 'What do they do in the evening', '', null),
  ('A2.U01.L01-FC01', 'A2.U01.L01', 'What is the goal of “Build a past-time account”?', 'tell a six-event weekend account using at least four accurate past forms and three sequence markers.', '', null),
  ('A2.U01.L02-FC01', 'A2.U01.L02', 'What is the goal of “Add a reaction and a reason”?', 'write a 70–90-word account with an event, reaction, reason, and contrast.', '', null),
  ('A2.U01.L03-FC01', 'A2.U01.L03', 'Why did she like the market?', 'her cousin; fruit; it was lively', '', null),
  ('A2.U01.L03-FC02', 'A2.U01.L03', 'Why are they leaving home later today?', '10:30; yesterday; because the station is quieter in the morning', '', null),
  ('A2.U02.L01-FC01', 'A2.U02.L01', 'What is the goal of “Plan a journey from a timetable”?', 'retrieve four journey details and ask two accurate timetable questions.', '', null),
  ('A2.U02.L02-FC01', 'A2.U02.L02', 'What is the goal of “Explain a travel problem and request help”?', 'explain a travel problem and complete a four-turn help exchange, including one clarification.', '', null),
  ('A2.U02.L03-FC01', 'A2.U02.L03', 'What is the goal of “Compare accommodation and confirm a booking”?', 'compare two lodging options and confirm three booking details in a role-play.', '', null),
  ('A2.U03.L01-FC01', 'A2.U03.L01', 'I feel tired, but I don''t have a fever.” Ask symptom, start, fever?', 'sore throat; yesterday; no', '', null),
  ('A2.U03.L02-FC01', 'A2.U03.L02', 'What is the goal of “Give simple advice and understand instructions”?', 'give two relevant suggestions and follow three short care instructions.', '', null),
  ('A2.U03.L03-FC01', 'A2.U03.L03', 'What is the goal of “Make an appointment and summarize instructions”?', 'arrange an appointment by phone and accurately relay three appointment details.', '', null),
  ('A2.U04.L01-FC01', 'A2.U04.L01', 'What is the goal of “Describe duties and schedules”?', 'describe four work/study duties and compare a weekly schedule using have to accurately.', '', null),
  ('A2.U04.L02-FC01', 'A2.U04.L02', 'What is the goal of “Give advice and make a request at work”?', 'respond to a workplace problem with relevant advice and make one polite request.', '', null),
  ('A2.U04.L03-FC01', 'A2.U04.L03', 'What is the goal of “Write a practical work message”?', 'write an 80–100-word work/study message with a problem, relevant detail, request, and next step.', '', null),
  ('A2.U05.L01-FC01', 'A2.U05.L01', 'What is the goal of “Explain intentions and arrangements”?', 'describe three plans and distinguish an intention from a fixed arrangement.', '', null),
  ('A2.U05.L02-FC01', 'A2.U05.L02', 'What is the goal of “Make predictions and spontaneous offers”?', 'respond to four situations using a context-appropriate prediction, offer, or intention.', '', null),
  ('A2.U05.L03-FC01', 'A2.U05.L03', 'What is the goal of “Negotiate a plan and send a confirmation”?', 'negotiate a plan, resolve one conflict, and write a 70–90-word confirmation with complete details.', '', null),
  ('A2.U06.L01-FC01', 'A2.U06.L01', 'given three prices (£6, £8, £10), which is the cheapest?', 'the £6 option', '', null),
  ('A2.U06.L02-FC01', 'A2.U06.L02', 'What is the goal of “Compare experiences and express preferences”?', 'give an opinion with two supporting comparisons and respond to a different preference.', '', null),
  ('A2.U06.L03-FC01', 'A2.U06.L03', 'Where did the learner go?', 'What did they do', '', null),
  ('A2.U06.L03-FC02', 'A2.U06.L03', 'What was the weather like?', 'What is planned for next month', '', null),
  ('B1.U01.L01-FC01', 'B1.U01.L01', 'What is the goal of “Tell a personal story with time order”?', 'narrate a short personal event in sequence using at least four past forms and three sequence markers.', '', null),
  ('B1.U01.L02-FC01', 'B1.U01.L02', 'Now I feel more confident.” Which idea is the strongest result?', 'the speaker feels more confident now', '', null),
  ('B1.U01.L03-FC01', 'B1.U01.L03', 'What is the goal of “Summarize a personal experience”?', 'give a short spoken summary of an experience with reason, result, and reflection.', '', null),
  ('B1.U02.L01-FC01', 'B1.U02.L01', 'I prefer a mixed model because it combines independence with teacher support.” Which word introduces contrast?', 'but', '', null),
  ('B1.U02.L02-FC01', 'B1.U02.L02', 'What is the goal of “Build a paragraph with reasons and examples”?', 'write a 120–150-word opinion paragraph with a clear point, reasons, and a conclusion.', '', null),
  ('B1.U02.L03-FC01', 'B1.U02.L03', 'What is the goal of “Respond to a counterargument”?', 'acknowledge an opposing view and still defend a position with evidence or experience.', '', null),
  ('B1.U03.L01-FC01', 'B1.U03.L01', 'The main reason is limited staffing.” Which is the main cause?', 'limited staffing', '', null),
  ('B1.U03.L01-FC02', 'B1.U03.L01', 'What is the direct effect?', 'students cannot finish group work after six', '', null),
  ('B1.U03.L02-FC01', 'B1.U03.L02', 'Reading:** “The city should test a later bus service for three months and publish the results.” Which part is the recommendation?', 'test a later bus service and publish results', '', null),
  ('B1.U03.L02-FC02', 'B1.U03.L02', 'What is the trade-off?', 'cost / service resources / reduced parking etc', '', null),
  ('B1.U03.L03-FC01', 'B1.U03.L03', 'What action does the writer recommend?', 'unreliable peak-time buses; loss of some parking; a three-month test with published results', '', null),
  ('B1.U03.L03-FC02', 'B1.U03.L03', 'What evidence is needed?', 'evening students; a later bus; evidence of sufficient use', '', null),
  ('B1.U03.L04-FC01', 'B1.U03.L04', 'What action does the writer recommend?', 'unreliable peak-time buses; loss of some parking; a three-month test with published results', '', null),
  ('B1.U03.L04-FC02', 'B1.U03.L04', 'What evidence is needed?', 'evening students; a later bus; evidence of sufficient use', '', null),
  ('B1.U04.L01-FC01', 'B1.U04.L01', 'What is the goal of “Describe responsibilities and routine work”?', 'describe work or study responsibilities using present simple and adverbs of frequency.', '', null),
  ('B1.U04.L02-FC01', 'B1.U04.L02', 'The final report recommended clearer deadlines and regular check-ins.” What caused the delay?', 'training was delayed', '', null),
  ('B1.U04.L02-FC02', 'B1.U04.L02', 'What remedy was recommended?', 'clearer deadlines and regular check-ins', '', null),
  ('B1.U04.L03-FC01', 'B1.U04.L03', 'What is the goal of “Explain a difficult situation and a plan”?', 'explain a problem, suggest a plan, and give a realistic timeline.', '', null),
  ('B1.U05.L01-FC01', 'B1.U05.L01', 'The main challenge is that drivers need time to adapt.” What are the benefits?', 'reduces congestion and improves health', '', null),
  ('B1.U05.L01-FC02', 'B1.U05.L01', 'What is the disadvantage?', 'less parking space', '', null),
  ('B1.U05.L02-FC01', 'B1.U05.L02', 'What is the goal of “Write a balanced paragraph”?', 'write a 150–180-word paragraph that presents a problem, two sides, and a recommendation.', '', null),
  ('B1.U05.L03-FC01', 'B1.U05.L03', 'What is the goal of “Speak and mediate on a public issue”?', 'summarize a discussion and relay a position neutrally to another person.', '', null),
  ('B1.U06.L01-FC01', 'B1.U06.L01', 'A second article includes charts and a clear method, but it covers only one region.” Which is more reliable?', 'the second article because it gives method and scope', '', null),
  ('B1.U06.L01-FC02', 'B1.U06.L01', 'What is the limitation?', 'only one region', '', null),
  ('B1.U06.L02-FC01', 'B1.U06.L02', 'What is the goal of “Compare digital and face-to-face learning”?', 'discuss and justify a preference between two learning modes.', '', null),
  ('B1.U06.L03-FC01', 'B1.U06.L03', 'What is the writer’s opinion?', 'delays and congestion; comfort; invest more in buses and trains; governments should reduce pollution and save time', '', null),
  ('B1.U06.L03-FC02', 'B1.U06.L03', 'What is the problem described?', 'Why do people still prefer cars', '', null),
  ('B1.U06.L03-FC03', 'B1.U06.L03', 'What is the proposed solution?', 'What is the writer’s opinion', '', null),
  ('B2.U01.L01-FC01', 'B2.U01.L01', 'The pilot had 120 students and no comparison group.” Which word shows measurement?', 'improved and 120 students', '', null),
  ('B2.U01.L01-FC02', 'B2.U01.L01', 'What is the key limitation?', 'no comparison group', '', null),
  ('B2.U01.L02-FC01', 'B2.U01.L02', 'What is the goal of “Build a structured argument with cautious language”?', 'write a short argument paragraph that includes a claim, evidence, a limitation, and a response to a possible objection.', '', null),
  ('B2.U01.L03-FC01', 'B2.U01.L03', 'Which conclusion is justified?', 'slightly higher attendance and student reports; one department, six weeks, 42 volunteers; the pilot is promising but insufficient to establish institution-wide effectiveness', '', null),
  ('B2.U01.L03-FC02', 'B2.U01.L03', 'Which additional groups or data are proposed?', 'reduced travel/focus; access to campus services; other courses and non-volunteers', '', null),
  ('B2.U01.L04-FC01', 'B2.U01.L04', 'Which conclusion is justified?', 'slightly higher attendance and student reports; one department, six weeks, 42 volunteers; the pilot is promising but insufficient to establish institution-wide effectiveness', '', null),
  ('B2.U01.L04-FC02', 'B2.U01.L04', 'Which additional groups or data are proposed?', 'reduced travel/focus; access to campus services; other courses and non-volunteers', '', null),
  ('B2.U02.L01-FC01', 'B2.U02.L01', 'The article uses interviews with business owners and optimistic language, but no independent figures are provided.” What is the claim?', 'new shopping district will create jobs and improve the city center', '', null),
  ('B2.U02.L01-FC02', 'B2.U02.L01', 'What is missing?', 'independent figures or data', '', null),
  ('B2.U02.L01-FC03', 'B2.U02.L01', 'How does the tone affect the argument?', 'optimistic language, with limited evidence', '', null),
  ('B2.U02.L02-FC01', 'B2.U02.L02', 'It uses images of children and quiet streets, but it does not mention the cost or the disruption during the building phase.” What does the video emphasize?', 'safety and family concerns', '', null),
  ('B2.U02.L02-FC02', 'B2.U02.L02', 'What is missing?', 'cost and disruption', '', null),
  ('B2.U02.L03-FC01', 'B2.U02.L03', 'What is the goal of “Respond to a claim in a formal discussion”?', 'answer a media or policy claim politely but clearly, with a reason and a counterexample.', '', null),
  ('B2.U03.L01-FC01', 'B2.U03.L01', 'A small grant for transport could increase access, but it would require local funding and oversight.” What is the problem?', 'unreliable transport', '', null),
  ('B2.U03.L01-FC02', 'B2.U03.L01', 'What is the proposed solution?', 'a small grant for transport', '', null),
  ('B2.U03.L01-FC03', 'B2.U03.L01', 'What is the trade-off?', 'local funding and oversight', '', null),
  ('B2.U03.L02-FC01', 'B2.U03.L02', 'What is the goal of “Write a balanced policy paragraph”?', 'write 200–250 words arguing for or against a policy change in education, transport, or public services.', '', null),
  ('B2.U03.L03-FC01', 'B2.U03.L03', 'What is the goal of “Present and mediate a policy recommendation”?', 'speak for 1–2 minutes on a social issue and then relay the decision in neutral language.', '', null),
  ('B2.U04.L01-FC01', 'B2.U04.L01', 'Staff questioned whether it was sustainable.” Which term indicates a concern about long-term viability?', 'sustainable', '', null),
  ('B2.U04.L01-FC02', 'B2.U04.L01', 'What is the downside of the cost-saving policy?', 'slower customer response and higher stress', '', null),
  ('B2.U04.L02-FC01', 'B2.U04.L02', 'What is the goal of “Write a brief recommendation for a policy or strategy”?', 'produce a concise recommendation with safeguards, risk, and evaluation.', '', null),
  ('B2.U04.L03-FC01', 'B2.U04.L03', 'What is the goal of “Deliver a short presentation and answer questions”?', 'present a structured viewpoint in 1–2 minutes and answer brief follow-up questions.', '', null),
  ('B2.U05.L01-FC01', 'B2.U05.L01', 'The report noted that results may be linked to motivation and self-selection, and it did not compare the exercise with other treatments.” What can be concluded?', 'the results are promising but limited', '', null),
  ('B2.U05.L01-FC02', 'B2.U05.L01', 'Why cautious?', 'small sample and no comparison group', '', null),
  ('B2.U05.L02-FC01', 'B2.U05.L02', 'What is the goal of “Present a recommendation with conditions”?', 'formulate a recommendation under conditions, including a reason and a safeguard.', '', null),
  ('B2.U05.L03-FC01', 'B2.U05.L03', 'What is the goal of “Explain uncertainty and respond to a challenge”?', 'answer a challenge to a recommendation by acknowledging uncertainty and explaining the next evidence needed.', '', null),
  ('B2.U06.L01-FC01', 'B2.U06.L01', 'The main challenge is not opposition, but misunderstanding.” What is the central tension?', 'benefits of exchange versus difficulty of interpretation', '', null),
  ('B2.U06.L01-FC02', 'B2.U06.L01', 'What is the challenge?', 'misunderstanding rather than open rejection', '', null),
  ('B2.U06.L02-FC01', 'B2.U06.L02', 'What is the goal of “Write a formal opinion essay”?', 'write a 250–300-word essay on a global or cultural issue, using thesis, supporting points, and a counterargument.', '', null),
  ('B2.U06.L03-FC01', 'B2.U06.L03', 'What does the final sentence suggest about the best model?', 'digital learning is useful but not sufficient; students need feedback and interaction; blended learning is likely best', '', null),
  ('B2.U06.L03-FC02', 'B2.U06.L03', 'What is the main claim?', 'Why does the writer say face-to-face teaching still matters', '', null),
  ('C1.U01.L01-FC01', 'C1.U01.L01', 'What is the goal of “Map an argument”?', 'label a passage''s claim, evidence, qualification, and conclusion, each with a text cue.', '', null),
  ('C1.U01.L02-FC01', 'C1.U01.L02', 'What is the goal of “Follow cohesion and scope”?', 'trace two reference or connective links and identify the scope of a claim.', '', null),
  ('C1.U01.L03-FC01', 'C1.U01.L03', 'What is the goal of “Write an analytical summary”?', 'write a 70–90-word summary retaining evidence, limitation, and implication.', '', null),
  ('C1.U02.L01-FC01', 'C1.U02.L01', 'What is the goal of “Plan for a decision reader”?', 'organize a report note around a decision question, evidence, limitation, recommendation, and next check.', '', null),
  ('C1.U02.L02-FC01', 'C1.U02.L02', 'What is the goal of “Edit agency and register”?', 'revise nominalized or passive wording when it hides a relevant actor, without making the tone less professional.', '', null),
  ('C1.U02.L03-FC01', 'C1.U02.L03', 'What is the goal of “Draft an evidence-based note”?', 'produce a 70–100-word manager note including evidence, limitation, and action.', '', null)
insert into public.flashcards (id, lesson_id, question, answer, phonetic, audio_url) values
  ('C1.U03.L01-FC01', 'C1.U03.L01', 'What is the goal of “Build a spoken argument map”?', 'plan a short talk with claim, evidence, limitation, and decision rule.', '', null),
  ('C1.U03.L02-FC01', 'C1.U03.L02', 'What is the goal of “Make relations audible”?', 'use signposting and pausing to make two reasoning relations clear in a spoken explanation.', '', null),
  ('C1.U03.L03-FC01', 'C1.U03.L03', 'What is the goal of “Respond and repair”?', 'answer a challenge question relevantly and clarify one ambiguous term.', '', null),
  ('C1.U04.L01-FC01', 'C1.U04.L01', 'What is the goal of “Infer stance from cues”?', 'support a stance inference with two wording/context cues and label it as inference.', '', null),
  ('C1.U04.L02-FC01', 'C1.U04.L02', 'What is the goal of “Interpret irony cautiously”?', 'compare a literal and a plausible ironic reading and state what remains uncertain.', '', null),
  ('C1.U04.L03-FC01', 'C1.U04.L03', 'What is the goal of “Paraphrase implication”?', 'produce a neutral paraphrase and a clearly labeled inference from the same input.', '', null),
  ('C1.U05.L01-FC01', 'C1.U05.L01', 'What is the goal of “Compare methods and constructs”?', 'state what two sources measure and whether they support a common outcome claim.', '', null),
  ('C1.U05.L02-FC01', 'C1.U05.L02', 'Can either source prove that flexible schedules improve productivity?', 'self-reported commute stress; difficulty collaborating without shared hours; no, neither measures productivity causally', '', null),
  ('C1.U05.L03-FC01', 'C1.U05.L03', 'What is the goal of “Synthesize and qualify”?', 'write a 70–100-word synthesis that attributes both sources, identifies one shared theme and one difference, and proposes no unsupported conclusion.', '', null),
  ('C1.U06.L01-FC01', 'C1.U06.L01', 'What is the goal of “Listen for interests”?', 'distinguish a stakeholder''s stated position from the interest or constraint it may represent.', '', null),
  ('C1.U06.L02-FC01', 'C1.U06.L02', 'What is the goal of “Negotiate conditional options”?', 'formulate an option with a clear condition and confirm whether it is accepted.', '', null),
  ('C1.U06.L03-FC01', 'C1.U06.L03', 'What is the goal of “Mediate the decision”?', 'relay the decision and one unresolved issue to a new audience without altering either.', '', null),
  ('C2.U01.L01-FC01', 'C2.U01.L01', 'What is the goal of “Choose precise words in context”?', 'distinguish the contextual force of four near-synonyms and justify a choice with the source''s communicative purpose.', '', null),
  ('C2.U01.L02-FC01', 'C2.U01.L02', 'What is the goal of “Edit commitment and focus”?', 'revise a short passage without changing date, quantity, condition, scope, or modality.', '', null),
  ('C2.U01.L03-FC01', 'C2.U01.L03', 'What is the goal of “Adapt two audience versions”?', 'produce two audience-specific versions and explain one deliberate change that does not alter the evidence.', '', null),
  ('C2.U02.L01-FC01', 'C2.U02.L01', 'What is the goal of “Reconstruct premises”?', 'distinguish explicit proposition, presupposition, entailment, and defeasible implication in a dense short argument.', '', null),
  ('C2.U02.L02-FC01', 'C2.U02.L02', 'What is the goal of “Rank competing readings”?', 'rank three interpretations by textual support and explain why one plausible claim is unsupported.', '', null),
  ('C2.U02.L03-FC01', 'C2.U02.L03', 'What is the goal of “Write interpretive commentary”?', 'write a 120–160-word commentary separating explicit content, inference, and unknown, with an alternative interpretation.', '', null),
  ('C2.U03.L01-FC01', 'C2.U03.L01', 'What is the goal of “Shape an address for an audience”?', 'organize an address with a claim, progression, and close suited to a stated audience.', '', null),
  ('C2.U03.L02-FC01', 'C2.U03.L02', 'What is the goal of “Control parallelism and emphasis”?', 'use one parallel contrast to sharpen a distinction without exaggerating evidence.', '', null),
  ('C2.U03.L03-FC01', 'C2.U03.L03', 'What is the goal of “Answer adversarial questions”?', 'answer two challenging questions by acknowledging their premise, addressing evidence or values, and preserving qualifications.', '', null),
  ('C2.U04.L01-FC01', 'C2.U04.L01', 'What is the goal of “Map authority, interests, and unknowns”?', 'record each stakeholder''s position, condition, authority, and unknown before negotiation.', '', null),
  ('C2.U04.L02-FC01', 'C2.U04.L02', 'What does the proposed pilot test?', 'longer response times in two peak periods; weekend performance and broader causes; whether temporary staffing improves service within an acceptable cost', '', null),
  ('C2.U04.L03-FC01', 'C2.U04.L03', 'What is the goal of “Write and verify a decision record”?', 'produce a concise record that names decision, actor, condition, owner, measure, review date, and unresolved issue.', '', null),
  ('C2.U05.L01-FC01', 'C2.U05.L01', 'What is the goal of “Audit the claim chain”?', 'trace a report''s evidence, alternative explanation, limit, and recommendation.', '', null),
  ('C2.U05.L02-FC01', 'C2.U05.L02', 'What is the goal of “Revise information focus and rhythm”?', 'revise sentence order and rhythm to foreground the decision boundary without changing claim strength.', '', null),
  ('C2.U05.L03-FC01', 'C2.U05.L03', 'What is the goal of “Edit for fidelity and concision”?', 'produce a 180–230-word evidence-based note and a revision note explaining an improvement that preserves meaning.', '', null),
  ('C2.U06.L01-FC01', 'C2.U06.L01', 'What is the goal of “Track exact commitments”?', 'distinguish a stated commitment, conditional plan, opinion, and inference in conflicting accounts.', '', null),
  ('C2.U06.L02-FC01', 'C2.U06.L02', 'What is the goal of “Test and repair understanding”?', 'ask a clarification question that tests scope or deadline and reformulate a partner''s position for confirmation.', '', null),
  ('C2.U06.L03-FC01', 'C2.U06.L03', 'What is the goal of “Mediate for two audiences”?', 'create specialist and public summaries that preserve the same condition and uncertainty.', '', null),
  ('POST-C2.T01.L01-FC01', 'POST-C2.T01.L01', 'What is the goal of “Read a study as an argument”?', 'annotate a short abstract for question, sample, method, result, limitation, and claim, and identify one claim that exceeds the reported evidence.', '', null),
  ('POST-C2.T01.L02-FC01', 'POST-C2.T01.L02', 'What is the goal of “Synthesize sources and qualify a claim”?', 'produce a thematic synthesis of two sources, preserving their different constructs and limitations.', '', null),
  ('POST-C2.T01.L03-FC01', 'POST-C2.T01.L03', 'What is the goal of “Write and present a research brief”?', 'create a concise research brief with a question, method, findings, limitation, and appropriately bounded implication.', '', null),
  ('POST-C2.T02.L01-FC01', 'POST-C2.T02.L01', 'What is the goal of “Frame a decision brief”?', 'distinguish decision, evidence, risk, owner, deadline, and unresolved question in a short workplace brief.', '', null),
  ('POST-C2.T02.L02-FC01', 'POST-C2.T02.L02', 'What is the goal of “Listen, clarify, and negotiate constraints”?', 'capture each stakeholder’s condition, ask a clarifying question, and restate a proposed agreement accurately.', '', null),
  ('POST-C2.T02.L03-FC01', 'POST-C2.T02.L03', 'What is the goal of “Deliver difficult news and document action”?', 'give a direct, respectful update that states the change, reason, effect, next step, and contact route.', '', null),
  ('POST-C2.T03.L01-FC01', 'POST-C2.T03.L01', 'Does the sentence present release as certain or merely possible?', 'the review is complete; from 1 June onward; it states that it will be available, not that it may be', '', null),
  ('POST-C2.T03.L02-FC01', 'POST-C2.T03.L02', 'What is the goal of “Diagnose before rewriting”?', 'annotate a draft for ambiguity, unsupported claims, repetition, hidden agency, and audience mismatch before editing it.', '', null),
  ('POST-C2.T03.L03-FC01', 'POST-C2.T03.L03', 'What is the goal of “Edit for flow, register, and fidelity”?', 'produce two audience-specific revisions of the same short message and explain how wording affects emphasis and commitment.', '', null),
  ('POST-C2.T04.L01-FC01', 'POST-C2.T04.L01', 'What is the goal of “Build an argument listeners can follow”?', 'outline a talk with a question, claim, evidence, qualification, counterargument, and decision request.', '', null),
  ('POST-C2.T04.L02-FC01', 'POST-C2.T04.L02', 'What is the goal of “Handle questions and chair disagreement”?', 'answer a challenge, clarify a term, and summarize two positions fairly before moving a discussion forward.', '', null),
  ('POST-C2.T04.L03-FC01', 'POST-C2.T04.L03', 'What is the goal of “Rehearse delivery and adapt to audience”?', 'adapt an argument for a specialist and a public audience while preserving its evidence and decision.', '', null),
  ('POST-C2.T05.L01-FC01', 'POST-C2.T05.L01', 'What is the goal of “Analyze the source before translating”?', 'identify proposition, actor, time, modality, register, implied relationship, and unresolved ambiguity before drafting a translation.', '', null),
  ('POST-C2.T05.L02-FC01', 'POST-C2.T05.L02', 'What is the goal of “Compare translations and mediate meaning”?', 'compare two translations for proposition, register, audience, and pragmatic effect; explain a preferred version and one residual loss.', '', null),
  ('POST-C2.T05.L03-FC01', 'POST-C2.T05.L03', 'What is the goal of “Revise translation and explain uncertainty”?', 'deliver a translation plus a concise translator’s note identifying ambiguity, chosen interpretation, and a question that would resolve it.', '', null),
  ('POST-C2.T06.L01-FC01', 'POST-C2.T06.L01', 'What is the goal of “Trace framing and agency”?', 'compare two short accounts of the same event for actor, agency, evaluation, and omitted information.', '', null),
  ('POST-C2.T06.L02-FC01', 'POST-C2.T06.L02', 'What is the goal of “Analyze stance, implicature, and audience”?', 'explain an explicit proposition and one context-dependent implication, then state what additional context would support or weaken that reading.', '', null),
  ('POST-C2.T06.L03-FC01', 'POST-C2.T06.L03', 'What is the goal of “Evaluate rhetorical effects and write an analysis”?', 'produce a short discourse analysis linking at least three textual features to plausible audience effects, with evidence and limits.', '', null)
